34:static char const *asn1_type_classes[4] = {"Universal", "Application", "Context-specific", "Private"};
35:
36:static char const *asn1_universal_types[] = {
37:    "End-of-Content",    "BOOLEAN",           "INTEGER",       "BIT STRING",     "OCTET STRING",    "NULL",
38:    "OBJECT IDENTIFIER", "Object Descriptor", "EXTERNAL",      "REAL",           "ENUMERATED",      "EMBEDDED PDV",
39:    "UTF8String",        "RELATIVE-OID",      "Reserved (16)", "Reserved (17)",  "SEQUENCE",        "SET",
40:    "NumericString",     "PrintableString",   "T61String",     "VideotexString", "IA5String",       "UTCTime",
41:    "GeneralizedTime",   "GraphicString",     "VisibleString", "GeneralString",  "UniversalString", "CHARACTER STRING",
42:    "BMPString"};
43:
44:static size_t nb_asn1_universal_types = sizeof(asn1_universal_types) / sizeof(char const *);
45:
46:static void ptls_asn1_print_indent(int level, ptls_minicrypto_log_ctx_t *log_ctx)
47:{
48:    for (int indent = 0; indent <= level; indent++) {
49:        log_ctx->fn(log_ctx->ctx, "   ");
50:    }
51:}
52:
53:size_t ptls_asn1_error_message(char const *error_label, size_t bytes_max, size_t byte_index, int level,
54:                               ptls_minicrypto_log_ctx_t *log_ctx)
55:{
56:    if (log_ctx != NULL) {
57:        ptls_asn1_print_indent(level, log_ctx);
58:        log_ctx->fn(log_ctx->ctx, "Error: %s (near position: %d (0x%x) out of %d)", error_label, (int)byte_index,
59:                    (uint32_t)byte_index, (int)bytes_max);
60:    }
61:    return byte_index;
62:}
63:
64:void ptls_asn1_dump_content(const uint8_t *bytes, size_t bytes_max, size_t byte_index, ptls_minicrypto_log_ctx_t *log_ctx)
65:{
66:    if (log_ctx != NULL && bytes_max > byte_index) {
67:        size_t nb_bytes = bytes_max - byte_index;
68:
69:        log_ctx->fn(log_ctx->ctx, " ");
70:
71:        for (size_t i = 0; i < 16 && i < nb_bytes; i++) {
72:            log_ctx->fn(log_ctx->ctx, "%02x", bytes[byte_index + i]);
73:        }
74:
75:        if (nb_bytes > 16) {
76:            log_ctx->fn(log_ctx->ctx, "...");
77:        }
78:    }
79:}
